def create_singleton_version_range(version: str, prereleases: bool | None = None) -> str:
    """Create a version range that contains only a single version. version: A PEP 440 compliant version string, e.g. '1.0' -> '{1.0}'. prereleases: Whether to include pre-release versions; if None, uses the default behavior."""
