from packaging.specifiers import SpecifierSet


def version_range_union(left: str, right: str) -> str:
    """Find the union of two version ranges. left: A version specifier string for the left range, right: A version specifier string for the right range."""
    try:
        left_range = SpecifierSet(left).to_range()
        right_range = SpecifierSet(right).to_range()
        result = left_range | right_range
        return str(result.to_specifier_set())
    except Exception as e:
        raise ValueError(f"Invalid version range specification: {e}")
