from packaging.specifiers import SpecifierSet


def version_in_specifier_set(version: str, specifier_set: str) -> bool:
    """Check if a version is contained within a specifier set. version: A version string to check against the specifier set, e.g. '3.2' specifier_set: A string representation of a version specifier set, e.g. '>=3.0,!=3.1' -> true."""
    try:
