from packaging.specifiers import Specifier


def version_in_specifier(version: str, specifier: str) -> bool:
    """Check if a version is contained within a specifier. version: A version string to check against the specifier, e.g. '1.2.3' -> true for specifier '>=1.0'. specifier: A version specifier string (e.g., '>=1.0', '==1.2.3')."""
    try:
        spec = Specifier(specifier)
