from packaging.tags import Tag


def tag_contains(tag: str, other_tag: str) -> bool:
    """Check if a tag is contained in another tag. tag: The tag to check if it contains the other tag, in the format 'interpreter-abi-platform' -> true if other_tag is contained within tag. Example: tag_contains('cp39-cp39-linux_x86_64', 'cp39-cp39-manylinux2014_x86_64') -> true."""
    try:
        tag_obj = Tag(*tag.split('-'))
        other_tag_obj = Tag(*other_tag.split('-'))
        return other_tag_obj in tag_obj
    except ValueError as e:
        raise ValueError(f"invalid tag format: {e}")
    except Exception as e:
        raise ValueError(f"error processing tags: {e}")
